insert into public.questions (id, subject, grade, category, difficulty, body, answer, distractors, explanation, image_url) values
  ('sci_1_001', '理科', 1, '音の性質', 1, 'おんさをたたき、水の入った水槽の水面にふれさせると、水しぶきが上がった。このことから、おんさが何をしていることがわかるか。', '振動している', array['回転している', '膨張している', '発熱している'], '音を出しているおんさを水につけると水しぶきが上がることから、おんさが振動していることがわかる。指で振動を止めると音は鳴りやむ。', null),
  ('sci_1_002', '理科', 1, '音の性質', 1, 'たいこやスピーカーなど、振動して音を出すものを何というか。', '音源（発音体）', array['導体', '共鳴板', '振り子'], '音を出すものを音源（発音体）という。音源はすべて振動している。', null),
  ('sci_1_003', '理科', 1, '音の性質', 1, 'おんさをたたくと、おんさの振動が何を振動させて、音として耳に伝わるか。', '空気', array['光', '糸', '地面'], '音源の振動がまわりの空気を振動させ、空気が濃くなったりうすくなったりしながら次々に振動を伝えることで音が伝わる。', null),
  ('sci_1_004', '理科', 1, '音の性質', 1, 'ピストルの音が離れた走者に届くのは、ピストルのまわりの空気が振動して、何となって広がるからか。', '波', array['電流', '熱', '風'], '音は空気中を波として広がりながら伝わる。', null),
  ('sci_1_005', '理科', 1, '音の性質', 2, '音は、音源となる物体が振動することによって生じる。このように振動が次々と伝わる現象を何というか。', '波', array['対流', '反射', '放電'], '花火の音で窓ガラスがゆれるのは、空気が振動し、その振動が波として次々に伝わるためである。', null),
  ('sci_1_006', '理科', 1, '音の性質', 1, '空気中を伝わってきた音の振動を、耳の中にある何でとらえているか。', '鼓膜', array['水晶体', '声帯', '三半規管'], '空気の振動が鼓膜を振動させ、その振動が信号に変えられて神経を通って脳に伝わり、「音が聞こえた」と感じ取る。', null),
  ('sci_1_007', '理科', 1, '音の性質', 2, '鳴り続けているブザーを密閉したガラス容器に入れ、真空ポンプで容器の中の空気をぬいていくと、聞こえるブザーの音はどうなるか。', '小さくなる', array['大きくなる', '高くなる', '変わらない'], '音の振動を伝える空気が少なくなるため、音は伝わりにくくなり小さくなる。完全な真空になると音は聞こえなくなる。', null),
  ('sci_1_008', '理科', 1, '音の性質', 2, '容器内の空気をぬくとブザーの音が小さくなり、空気を再び入れると音が大きくなった。この実験からわかることは何か。', '空気が音を伝えていること', array['空気が音をさえぎっていること', 'ブザーが真空中では振動しないこと', '音の高さが気圧によって変わること'], '空気の量と音の大きさが対応して変化することから、空気が音（振動）を伝えていることがわかる。', null),
  ('sci_1_009', '理科', 1, '音の性質', 2, '真空実験で、ブザーのそばに発泡ポリスチレンの球を置いておくのは、何を確かめるためか。', 'ブザーが振動しているかどうか', array['音が聞こえるかどうか', '容器の中に空気があるかどうか', '容器の温度が変化したかどうか'], '音が聞こえなくなってもブザー自体が振動しているかどうかは、そばに置いた発泡ポリスチレン球の動きで確認できる。', null),
  ('sci_1_010', '理科', 1, '音の性質', 2, '同じ高さの音が出るおんさAとBを向かい合わせに置き、Aをたたくと、Bはどうなるか。', '鳴りだす', array['何も変化しない', '倒れる', 'Aより高い音で鳴る'], 'Aの振動が空気を振動させ、その振動が空気中を伝わってBのおんさを振動させるため、Bも鳴りだす。', null),
  ('sci_1_011', '理科', 1, '音の性質', 2, '向かい合わせたおんさAとBで、Aをたたいた後にAを手でおさえると、Bはどうなるか。', 'そのまま鳴り続ける', array['すぐに音が止まる', '音が大きくなる', '音が高くなる'], 'Aの振動を止めてもBはすでに振動を始めているので、Bはそのまま振動を続けて鳴り続ける。', null),
  ('sci_1_012', '理科', 1, '音の性質', 3, '向かい合わせたおんさAとBの間に板を入れてAをたたくと、Bはどうなると考えられるか。', '板がないときより小さな音が出る', array['板がないときより大きな音が出る', '板がないときと同じ大きさの音が出る', '板がないときより高い音が出る'], '板があると空気の振動がさえぎられてBに伝わりにくくなるため、板がない場合より小さな音になる（ほとんど振動しない）。', null),
  ('soc_1_001', '社会', 1, 'アジア州', 1, '中華人民共和国（中国）の首都はどこか。', 'ペキン', array['シャンハイ', 'ホンコン', 'ナンキン'], '中国の首都はペキン（北京）。シャンハイは中国最大の経済都市だが首都ではない。', null),
  ('soc_1_002', '社会', 1, 'アジア州', 1, 'インドの首都はどこか。', 'デリー', array['ムンバイ', 'コルカタ', 'バンコク'], 'インドの首都はデリー。バンコクはタイの首都。', null),
  ('soc_1_003', '社会', 1, 'アジア州', 1, '韓国（大韓民国）の首都はどこか。', 'ソウル', array['ピョンヤン', 'プサン', 'インチョン'], '韓国の首都はソウル。ピョンヤンは北朝鮮の首都。', null),
  ('soc_1_004', '社会', 1, 'アジア州', 1, 'アジア州の区分のうち、日本・中国・韓国などが含まれる地域を何というか。', '東アジア', array['東南アジア', '南アジア', '中央アジア'], 'アジア州は東アジア・東南アジア・南アジア・西アジア・中央アジアなどに区分され、日本や中国、韓国は東アジアに含まれる。', null),
  ('soc_1_005', '社会', 1, 'アジア州', 2, 'タイやベトナム、インドネシアなどが含まれるアジアの地域区分はどれか。', '東南アジア', array['東アジア', '西アジア', '中央アジア'], 'インドシナ半島や島々の国々（タイ・ベトナム・マレーシア・インドネシアなど）は東南アジアに区分される。', null),
  ('soc_1_006', '社会', 1, 'アジア州', 2, '赤道が通る場所として正しいものはどれか。', '東南アジアのシンガポール付近', array['中国のペキン付近', 'インドのデリー付近', '日本の沖縄付近'], '赤道は南アメリカ大陸のアマゾン川流域、アフリカ大陸のギニア湾、東南アジアのシンガポール付近を通る。', null),
  ('soc_1_007', '社会', 1, 'アジア州', 1, '世界最高峰のエベレスト（チョモランマ）を含む、アジアの山脈は何か。', 'ヒマラヤ山脈', array['アンデス山脈', 'ロッキー山脈', 'アルプス山脈'], 'ヒマラヤ山脈はアルプス・ヒマラヤ造山帯に属する高くけわしい山脈で、その北にはチベット高原が広がる。', null),
  ('soc_1_008', '社会', 1, 'アジア州', 2, '高くけわしい山々がつらなる造山帯では、大地の動きがさかんである。造山帯でしばしば起こる災害はどれか。', '地震', array['干ばつ', '竜巻', '高潮'], 'アジアは環太平洋造山帯とアルプス・ヒマラヤ造山帯が交わる地域で、地震や火山の噴火が多い。', null),
  ('soc_1_009', '社会', 1, 'アジア州', 1, 'ASEAN諸国の米の生産に大きな影響を与えている、季節によって向きが変わる風を何というか。', 'モンスーン（季節風）', array['偏西風', '貿易風', 'からっ風'], 'アジアの東部・南部では半年ごとに風向きが逆になるモンスーン（季節風）がふき、稲作に大きな影響を与えている。', null),
  ('soc_1_010', '社会', 1, 'アジア州', 2, 'モンスーン（季節風）について正しく説明しているものはどれか。', '季節によって向きが変わり、夏は海洋から、冬は大陸から吹く風', array['1年を通して西から東へ吹く風', '台風が発生すると吹く強い風', '冷害の原因となる、夏に北東から吹く冷たい風'], 'モンスーンは夏に海から陸へ（湿った風→雨季）、冬に陸から海へ（乾いた風→乾季）と、半年ごとに向きが変わる。', null),
  ('soc_1_011', '社会', 1, 'アジア州', 3, 'インドのある地域では雨季に南西の季節風が吹く。この季節風の説明として適切なものはどれか。', '南西から北東に向かって吹く風で、乾季には風向きが変わる', array['南西から北東に向かって吹く風で、風向きは年中一定である', '北東から南西に向かって吹く風で、風向きは年中一定である', '北東から南西に向かって吹く風で、乾季にも同じ向きに吹く'], '「南西の季節風」は南西から北東へ吹く風。季節風なので、乾季（冬）には逆向き（北東から南西）に変わる。', null),
  ('soc_1_012', '社会', 1, 'アジア州', 2, '夏にインド洋からの湿った季節風がヒマラヤ山脈にぶつかると、山脈の南側ではどうなるか。', '大量の雨が降る', array['乾燥して砂漠になる', '気温が急に下がって雪だけが降る', '風がなくなり晴天が続く'], '湿った季節風が山脈にぶつかって上昇すると雲ができ、大量の雨を降らせる。', null),
  ('soc_1_013', '社会', 1, 'アジア州', 2, 'タイの首都バンコクの雨温図は、各月の気温が20℃以上で、雨の多い季節と少ない季節がある。バンコクの気候は何か。', 'サバナ気候', array['熱帯雨林気候', '地中海性気候', 'ステップ気候'], '気温が年中高いので熱帯。熱帯のうち、雨季と乾季があるのはサバナ気候（年中多雨なら熱帯雨林気候）。', null),
  ('soc_1_014', '社会', 1, 'アジア州', 2, '赤道直下にあり、1年を通して気温が高く雨が多いシンガポールの気候は何か。', '熱帯雨林気候', array['サバナ気候', '温帯湿潤気候', '砂漠気候'], '赤道直下のシンガポールは年中雨の多い熱帯雨林気候。雨季と乾季があるバンコクやコルカタはサバナ気候。', null),
  ('soc_1_015', '社会', 1, 'アジア州', 3, 'バンコクとシンガポールはともに熱帯に属するが、バンコクにあってシンガポールにはあまり見られない特徴はどれか。', '降水量が多い雨季と少ない乾季がある', array['1年を通して気温が低い', '冬に雪が降る', '1年中ほとんど雨が降らない'], 'シンガポール（熱帯雨林気候）は年中多雨だが、バンコク（サバナ気候）には雨季と乾季の区別がある。', null),
  ('sci_1_013', '理科', 1, '植物のつくりとはたらき', 1, '光合成でおもにつくられる養分はどれか。', 'デンプン', array['タンパク質', '脂肪', '無機養分'], '光合成では二酸化炭素と水からデンプンなどの有機物と酸素がつくられる。', null),
  ('sci_1_014', '理科', 1, '植物のつくりとはたらき', 1, '光合成の原料となるのは水とあと1つは何か。', '二酸化炭素', array['酸素', '窒素', 'アンモニア'], '葉の気孔から取り入れた二酸化炭素と根から吸い上げた水が原料になる。', null),
  ('sci_1_015', '理科', 1, '植物のつくりとはたらき', 1, '光合成が行われる細胞内の緑色の粒を何というか。', '葉緑体', array['核', '液胞', '細胞壁'], '葉緑体には緑色の色素クロロフィルが含まれ光エネルギーを吸収する。', null),
  ('sci_1_016', '理科', 1, '植物のつくりとはたらき', 1, '葉の表面にあり気体が出入りする小さなすきまを何というか。', '気孔', array['道管', '師管', '葉脈'], '気孔は2つの孔辺細胞にはさまれたすきまで葉の裏側に多い。', null),
  ('sci_1_017', '理科', 1, '植物のつくりとはたらき', 1, '植物の体内の水が水蒸気となって出ていくはたらきを何というか。', '蒸散', array['呼吸', '光合成', '発芽'], '蒸散がさかんになると根からの水の吸い上げも活発になる。', null),
  ('sci_1_018', '理科', 1, '植物のつくりとはたらき', 2, '根から吸収した水や水にとけた養分が通る管はどれか。', '道管', array['師管', '気孔', '葉緑体'], '道管は茎の中心側にあり水の通り道になる。師管は葉でできた養分の通り道。', null),
  ('sci_1_019', '理科', 1, '植物のつくりとはたらき', 2, '葉でつくられた養分が運ばれる管を何というか。', '師管', array['道管', '維管束', '気孔'], '師管は茎の外側にあり葉でつくられた養分を全身へ運ぶ。', null),
  ('sci_1_020', '理科', 1, '植物のつくりとはたらき', 2, 'デンプンがあることを確かめる薬品とそのときの色の組み合わせはどれか。', 'ヨウ素液で青紫色', array['ベネジクト液で青色', '石灰水で無色', 'BTB溶液で緑色'], 'ヨウ素液はデンプンと反応して青紫色に変化する。', null),
  ('sci_1_021', '理科', 1, '植物のつくりとはたらき', 3, '蒸散の実験で葉の表や裏にワセリンをぬるのはなぜか。', '水が出ていく場所を限定して比べるため', array['葉を枯れにくくするため', '光合成をさかんにするため', '葉の重さをそろえるため'], 'ぬった部分の気孔をふさぐことで表と裏どちらからの蒸散が多いかを比べられる。', null),
  ('sci_1_022', '理科', 1, '植物の分類', 1, '胚珠が子房に包まれている植物のなかまを何というか。', '被子植物', array['裸子植物', 'シダ植物', 'コケ植物'], '被子植物は子房があり受粉後に子房が果実になる。', null),
  ('sci_1_023', '理科', 1, '植物の分類', 2, 'マツやイチョウのように子房がなく胚珠がむき出しの植物を何というか。', '裸子植物', array['被子植物', 'シダ植物', 'ソウ類'], '裸子植物は子房がないため果実ができない。', null),
  ('sci_1_024', '理科', 1, '植物の分類', 1, '種子をつくらず胞子でふえ根・茎・葉の区別がある植物はどれか。', 'シダ植物', array['コケ植物', '裸子植物', '被子植物'], 'シダ植物は維管束をもち葉の裏の胞子のうで胞子をつくる。', null),
  ('sci_1_025', '理科', 1, '植物の分類', 2, '根・茎・葉の区別がなく体全体で水を吸収する植物はどれか。', 'コケ植物', array['シダ植物', '単子葉類', '双子葉類'], 'コケ植物には維管束がなく仮根はおもに体を固定する役目をもつ。', null),
  ('sci_1_026', '理科', 1, '植物の分類', 1, 'トウモロコシなど単子葉類の葉に見られる葉脈はどれか。', '平行脈', array['網状脈', '主根', '側根'], '単子葉類は子葉が1枚で葉脈は平行脈、根はひげ根になる。', null),
  ('sci_1_027', '理科', 1, '植物の分類', 2, '双子葉類の根のつくりとして正しいものはどれか。', '主根と側根', array['ひげ根', '仮根', '胞子のう'], '双子葉類は太い主根から細い側根が枝分かれしている。', null),
  ('sci_1_028', '理科', 1, '植物の分類', 2, '受粉したあと果実になるのは花のどの部分か。', '子房', array['胚珠', 'やく', 'がく'], '子房は果実に、その中の胚珠は種子になる。', null),
  ('sci_1_029', '理科', 1, '植物の分類', 3, 'マツの雌花のりん片についているものはどれか。', '胚珠', array['子房', '果実', '花弁'], 'マツには子房がなくりん片に胚珠がむき出しでついている。', null),
  ('sci_1_030', '理科', 1, '観察器具の使い方', 1, '顕微鏡で対物レンズを高倍率のものに変えると視野の明るさはどうなるか。', '暗くなる', array['明るくなる', '変わらない', '一度明るくなってから暗くなる'], '高倍率にするとせまい範囲を拡大するため視野は暗くせまくなる。', null),
  ('sci_1_031', '理科', 1, '観察器具の使い方', 2, '顕微鏡の倍率を高くしたとき見える範囲はどうなるか。', 'せまくなる', array['広くなる', '変わらない', '上下だけ広くなる'], '倍率を上げると拡大される分だけ観察できる範囲はせまくなる。', null),
  ('sci_1_032', '理科', 1, '観察器具の使い方', 2, '顕微鏡でレンズを取り付けるときの正しい順序はどれか。', '接眼レンズを先に付ける', array['対物レンズを先に付ける', '同時に付ける', 'どちらでもよい'], '先に接眼レンズを付けることで鏡筒の中にほこりが入るのを防げる。', null),
  ('sci_1_033', '理科', 1, '観察器具の使い方', 3, '顕微鏡のピントを合わせるときの正しい操作はどれか。', '対物レンズとプレパラートを遠ざけながら合わせる', array['対物レンズとプレパラートを近づけながら合わせる', '反射鏡を動かしながら合わせる', 'しぼりを回しながら合わせる'], '横から見て近づけたあと接眼レンズをのぞきながら遠ざけると衝突を防げる。', null),
  ('sci_1_034', '理科', 1, '観察器具の使い方', 2, '倍率は低いが立体的に観察できる顕微鏡を何というか。', '双眼実体顕微鏡', array['光学顕微鏡', '電子顕微鏡', 'ルーペ'], '双眼実体顕微鏡は両目で見るため厚みのある物を立体的に観察できる。', null),
  ('sci_1_035', '理科', 1, '観察器具の使い方', 2, 'ルーペで手に持てる小さな物を観察するときの正しい方法はどれか。', 'ルーペを目に近づけ観察物を動かす', array['ルーペを観察物に近づけ顔を動かす', 'ルーペを固定し体ごと動かす', 'ルーペを遠ざけて見る'], 'ルーペは目に近づけて固定し観察物のほうを前後に動かしてピントを合わせる。', null),
  ('sci_1_036', '理科', 1, '観察器具の使い方', 3, 'プレパラートをつくるときカバーガラスを端からゆっくりおろす理由はどれか。', '空気の泡が入らないようにするため', array['試料をつぶすため', '水を蒸発させるため', '倍率を上げるため'], '一気にかぶせると気泡が入り観察のじゃまになる。', null),
  ('sci_1_037', '理科', 1, '身のまわりの物質', 1, '砂糖やエタノールのように炭素を含み燃えると二酸化炭素を出す物質を何というか。', '有機物', array['無機物', '金属', '合金'], '有機物は炭素を含み加熱すると黒くこげて二酸化炭素と水を生じる。', null),
